"""Application services that depend on shared utilities."""

from __future__ import annotations

from datetime import date

from utils.dates import format_date
from utils.strings import slugify
from utils.validation import is_email, is_phone


def build_user_slug(first_name: str, last_name: str) -> str:
    return slugify(f"{first_name}-{last_name}")


def format_report_date(report_date: date) -> str:
    return format_date(report_date, "%B %d, %Y")


def validate_contact(email: str, phone: str) -> list[str]:
    errors: list[str] = []
    if not is_email(email):
        errors.append("invalid email")
    if not is_phone(phone):
        errors.append("invalid phone")
    return errors

