"""File-backed report storage."""

from __future__ import annotations

from pathlib import Path

from utils.files import file_exists, read_text_file, write_text_file
from utils.validation import is_safe_filename


def save_report(path: Path, content: str) -> None:
    if not is_safe_filename(path.name):
        raise ValueError(f"unsafe filename: {path.name}")
    write_text_file(path, content)


def load_report(path: Path) -> str:
    if not file_exists(path):
        raise FileNotFoundError(path)
    return read_text_file(path)

